-- ============================================
-- FIX — cours Intervalles / Valeur absolue / Inequations reecrits (pedagogie)
-- A coller dans : Supabase > SQL Editor > New query
-- ============================================
-- Meme traitement que pour Vecteurs : une idee a la fois, une image
-- concrete avant la formule, exemples pas a pas. Le contenu technique
-- ne change pas, seule la maniere de l'expliquer change.

UPDATE cours
SET contenu = $cj1$[{"id": 1, "type": "texte", "content": "Si on te dit « prends un nombre entre 2 et 5 », tu ne sais pas lequel — mais tu sais où chercher. Un intervalle, c'est exactement cette zone de recherche, écrite proprement."}, {"id": 2, "type": "definition", "content": "Chaque ensemble contient le précédent, comme des poupées russes imbriquées :\nℕ (entiers naturels : 0, 1, 2, 57…) est dans ℤ (entiers relatifs : −3, 0, 8…),\nqui est dans 𝔻 (décimaux : 0,25 ; −3,7…),\nqui est dans ℚ (fractions : 1/3 ; −7/4…),\nqui est dans ℝ (tous les nombres de la droite, irrationnels compris : √2, π).\n1/3 est rationnel mais pas décimal. √2 et π sont réels sans être rationnels — on dit irrationnels.", "titre": "Les ensembles de nombres, comme des poupées russes"}, {"id": 3, "type": "definition", "content": "2 ≤ x ≤ 5  →  [2 ; 5]  (2 et 5 inclus)\n2 < x < 5  →  ]2 ; 5[  (2 et 5 exclus)\n2 ≤ x < 5  →  [2 ; 5[  (2 inclus, 5 exclu)\nx ≥ 2  →  [2 ; +∞[  (tout à partir de 2)\nx < 5  →  ]−∞ ; 5[  (tout avant 5)", "titre": "Les intervalles : 5 formes à connaître"}, {"id": 4, "type": "remarque", "content": "Le crochet « mord » vers le nombre qu'il inclut, et s'ouvre vers l'extérieur pour celui qu'il exclut. ∞ n'est jamais atteint, donc toujours un crochet ouvert de son côté. On écrit x ∈ [2 ; 5] pour « x appartient à [2 ; 5] ».", "titre": "La règle du crochet"}, {"id": 5, "type": "definition", "content": "Intersection ∩ : les nombres qui sont dans les deux intervalles en même temps — c'est un « et ».\nRéunion ∪ : les nombres qui sont dans l'un ou dans l'autre — c'est un « ou ».", "titre": "Réunion et intersection : « ou » et « et »"}, {"id": 6, "type": "exemple", "content": "Place les deux intervalles sur la même droite, l'un sous l'autre, et regarde où ils se chevauchent (intersection) ou ce qu'ils couvrent à eux deux (réunion).\n[1 ; 5] ∩ [3 ; 8] = [3 ; 5]\n[1 ; 3] ∪ [2 ; 6] = [1 ; 6]\n]−∞ ; 2[ ∪ [2 ; +∞[ = ℝ\n]−∞ ; 2[ ∩ [2 ; +∞[ = ∅  (2 est dans le deuxième, pas dans le premier : aucun point commun)", "titre": "Le réflexe qui évite les erreurs : dessiner"}, {"id": 7, "type": "remarque", "content": "Oublier le sens du crochet : ]2 ; 5] et [2 ; 5] ne sont pas le même ensemble.\nÉcrire [2 ; 5] ∩ [7 ; 9] = [5 ; 7] : en réalité il n'y a aucun point commun, c'est ∅.\nPour une égalité comme x = 3 ou x = 5, on ne met pas d'intervalle : on liste les deux valeurs, {3 ; 5}.", "titre": "Pièges classiques"}, {"id": 8, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices — vas-y une fois le cours relu, ça se joue en quelques minutes.", "titre": "Pour aller plus loin"}]$cj1$
WHERE niveau = '2nde' AND chapitre = 'Intervalles et ensembles de nombres';

UPDATE cours
SET contenu = $cj2$[{"id": 1, "type": "texte", "content": "La valeur absolue d'un nombre, c'est sa distance à zéro — on efface juste le signe. |5| = 5 et |−5| = 5 : les deux sont à 5 pas de zéro, dans des directions opposées."}, {"id": 2, "type": "formule", "content": "|x| = \\begin{cases} x & \\text{si } x \\geq 0 \\\\ -x & \\text{si } x \\leq 0 \\end{cases}"}, {"id": 3, "type": "exemple", "content": "|5| = 5, |−3| = 3, |0| = 0. Une valeur absolue n'est jamais négative — une distance ne peut pas l'être."}, {"id": 4, "type": "definition", "content": "Sur la droite graduée, la distance entre a et b est la valeur absolue de leur différence. C'est la clé de tout le chapitre : dès que tu vois |x − a|, lis-le comme « la distance de x au point a ».", "titre": "La vraie idée : une distance entre deux nombres"}, {"id": 5, "type": "formule", "content": "d(a ; b) = |a - b| = |b - a|"}, {"id": 6, "type": "exemple", "content": "La distance entre −2 et 5 vaut |−2 − 5| = |−7| = 7."}, {"id": 7, "type": "methode", "content": "|x − a| = r  →  x = a − r ou x = a + r  (les deux points à distance r de a)\n|x − a| ≤ r  →  x ∈ [a − r ; a + r]  (les points à distance au plus r de a)\nLes versions strictes (< et >) suivent la même logique, avec des crochets ouverts.", "titre": "Résoudre avec une valeur absolue (r positif)"}, {"id": 8, "type": "remarque", "content": "Attention : le programme officiel de seconde ne demande que la distance entre deux nombres et le cas |x − a| ≤ r (intervalle centré en a). Les cas égalité et ≥ sont de bons entraînements, mais pas exigibles au contrôle."}, {"id": 9, "type": "exemple", "content": "|x − 3| = 2 : à distance 2 de 3. x = 1 ou x = 5.\n|x − 3| ≤ 2 : à distance au plus 2 de 3. x ∈ [1 ; 5].\n|x + 1| < 3 : on relit x + 1 comme x − (−1), le centre est −1. x ∈ ]−4 ; 2[.\n|x| = −2 : impossible, une valeur absolue n'est jamais négative. Aucune solution.", "titre": "Exemples résolus"}, {"id": 10, "type": "remarque", "content": "Pour |x + 1|, le centre est −1, pas +1 : il faut relire x + 1 en x − (−1).\n|a + b| n'est pas égal à |a| + |b| en général : |3 + (−5)| = 2, mais |3| + |−5| = 8.\nUne distance est toujours positive : jamais de résultat négatif.", "titre": "Pièges classiques"}, {"id": 11, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices.", "titre": "Pour aller plus loin"}]$cj2$
WHERE niveau = '2nde' AND chapitre = 'Valeur absolue et distance';

UPDATE cours
SET contenu = $cj3$[{"id": 1, "type": "texte", "content": "Résoudre une inéquation, c'est trouver tous les nombres x qui la rendent vraie — pas un seul nombre, mais toute une zone. La réponse est donc un intervalle, jamais un nombre tout seul."}, {"id": 2, "type": "theoreme", "content": "On peut ajouter ou soustraire le même nombre des deux côtés : le sens ne change pas.\nOn peut multiplier ou diviser par un nombre positif : le sens ne change pas.\nMultiplier ou diviser par un nombre négatif inverse le sens de l'inégalité.", "titre": "Les trois règles"}, {"id": 3, "type": "remarque", "content": "Pourquoi cette troisième règle ? 2 < 5, mais en multipliant par −1 on obtient −2 > −5 : les nombres se rangent dans l'ordre inverse une fois qu'on change leur signe."}, {"id": 4, "type": "methode", "content": "1. Développer s'il y a des parenthèses (attention au signe moins devant).\n2. Regrouper les x d'un côté, les nombres de l'autre, en changeant les signes de ce qu'on déplace.\n3. Diviser par le coefficient de x — en inversant le sens s'il est négatif.\n4. Écrire la solution sous forme d'intervalle.", "titre": "La méthode, dans l'ordre"}, {"id": 5, "type": "exemple", "content": "3x − 5 ≤ 7 : 3x ≤ 12, donc x ≤ 4. Solution : ]−∞ ; 4].\n−2x + 1 > 7 : −2x > 6, on divise par −2 donc on inverse : x < −3. Solution : ]−∞ ; −3[.\n2x + 1 ≥ 5x − 8 : −3x ≥ −9, on divise par −3 : x ≤ 3. Solution : ]−∞ ; 3].\nDouble inégalité −3 < 2x + 1 ≤ 7 : on retire 1 partout, −4 < 2x ≤ 6, puis on divise par 2 : −2 < x ≤ 3.", "titre": "Exemples résolus"}, {"id": 6, "type": "methode", "content": "Pour 2x + 1 ≥ 5x − 8, teste x = 0 (dans la solution ]−∞ ; 3]) : 1 ≥ −8, vrai. Teste x = 4 (hors solution) : 9 ≥ 12, faux. Les deux tests concordent : la solution est cohérente.", "titre": "Le réflexe pour vérifier : une valeur test"}, {"id": 7, "type": "remarque", "content": "Oublier d'inverser le sens en divisant par un négatif — c'est l'erreur n°1.\nSe tromper de crochet : ≤ et ≥ donnent un crochet fermé, < et > un crochet ouvert.\nÉcrire la solution sous la forme x = 4 : une inéquation a tout un ensemble de solutions, pas une seule valeur.", "titre": "Pièges classiques"}, {"id": 8, "type": "remarque", "content": "Les exercices progressifs de ce chapitre sont dans l'onglet Exercices.", "titre": "Pour aller plus loin"}]$cj3$
WHERE niveau = '2nde' AND chapitre = 'Inéquations du premier degré';
